  "ui.finalOnboarding.f54f5d4bcd": "Saját beállítások",
  "ui.finalOnboarding.7d2d594053": "Hogyan szeretnéd használni a Pixflow-t?",
  "ui.finalOnboarding.bdf73477f9": "API-szolgáltató csatlakoztatása",
  "ui.finalOnboarding.28edc3b8f2": "AI-előfizetés csatlakoztatása",
  "ui.finalOnboarding.f9573d1164": "Készen állsz az alkotásra",
  "ui.finalOnboarding.45ddd1221b": "A WordPress és Gutenberg szerkesztése ingyenes. Nem kell licenc vagy próbaidőszak.",
  "ui.finalOnboarding.6072f06060": "A kezdéshez aktiváld a licencedet. Már aktiváltad? Itt fog megjelenni.",
  "ui.finalOnboarding.ae83bc42b4": "Válaszd a neked megfelelő megoldást. A Beállításokban bármikor módosíthatod.",
  "ui.finalOnboarding.c9e2eb7fcb": "Használd a szolgáltatód API-kulcsát. Ehhez nem kell Bridge.",
  "ui.finalOnboarding.5add76d77c": "A Bridge összeköti ezt az oldalt a számítógépeden futó AI-ügynökökkel. Az AI-használatot a szolgáltatói fiókod biztosítja.",
  "ui.finalOnboarding.4813d31d25": "Használd a WordPress-munkaterületet AI csatlakoztatása nélkül.",
  "ui.finalOnboarding.fbcd710247": "A kapcsolat be van állítva. Kezdd egy kérdéssel, vagy írd le, mit szeretnél létrehozni.",
  "ui.finalOnboarding.24fba6f166": "AI-előfizetés csatlakoztatása",
  "ui.finalOnboarding.82d6b8daef": "Használj támogatott ügynököket, például Codexet vagy OpenCode-ot a Pixflow Design Bridge-en keresztül.",
  "ui.finalOnboarding.894f66ba11": "API-kulcs használata",
  "ui.finalOnboarding.e76c3bfd0e": "Csatlakozz közvetlenül a szolgáltatódhoz. Az API-használat külön kerül számlázásra.",
  "ui.finalOnboarding.1be451ef72": "Folytatás AI nélkül",
  "ui.finalOnboarding.88e6e83b86": "Használd a WordPress-munkaterületet. Később hozzáadhatsz AI-t, ha szeretnél.",
  "ui.finalOnboarding.105e56e56f": "Miért válaszd a helyi CLI-t?",
  "ui.finalOnboarding.5df057fcd7": "Az API-használat külön kerül számlázásra",
  "ui.finalOnboarding.44e30ed15f": "A BYOK használatához API-kulcs kell. Az AI-szolgáltató az API-használatot a CLI-előfizetéstől külön számlázza, ezért ez többletköltséget jelenthet a CLI-fiókhoz tartozó vagy heti keret felhasználása helyett.",
  "ui.finalOnboarding.5f9b0ae108": "Csak munkamenet",
  "ui.finalOnboarding.3c0e1f05da": "A kontextus csak a panel munkamenetének végéig marad meg. Újratöltéskor tiszta lappal indulsz.",
  "ui.finalOnboarding.3efe5537cf": "Visszaállítás újratöltés után",
  "ui.finalOnboarding.1ccaa4f4ad": "Korlátozott kontextus helyreállítása a böngészőlap újratöltése után.",
  "ui.finalOnboarding.a7f9620cca": "Ezen az eszközön",
  "ui.finalOnboarding.94536fb7d6": "Korlátozott helyi kontextus megőrzése az eszközön a böngésző újraindításai között.",
  "ui.finalOnboarding.1cd7c231fc": "A lebegő panel megőrzési beállítása frissült.",
  "ui.finalOnboarding.d5c52fc3a8": "Kontextus-visszaállítás kérve a nyitott Bricks-panelhez.",
  "ui.finalOnboarding.77d3d7f7d3": "Új beszélgetés kérve a nyitott Bricks-panelhez.",
  "ui.finalOnboarding.125903ce05": "A böngészőkörnyezet törlését kértük. A mentett beszélgetések megmaradnak.",
