  "ui.mediaStarter.image1.title": "Szerkesztőségi portré",
  "ui.mediaStarter.image1.tag": "Portré",
  "ui.mediaStarter.image1.prompt": "Közeli, szerkesztőségi stílusú portré egy húszas évei végén járó fiatal kreatív igazgatóról. Lágy természetes fény magas stúdióablakokon át, meleg semleges paletta (krém, szürkésbarna, lágy fekete), 85mm f/1.8 kis mélységélességgel, éles tekintet egyenesen a kamerába, finom filmszemcse, smink nélküli hatás.",
  "ui.mediaStarter.image2.title": "Termék főképe",
  "ui.mediaStarter.image2.tag": "E-kereskedelem",
  "ui.mediaStarter.image2.prompt": "Prémium termékfotó egyetlen matt kerámia kávésbögréről, meleg krémszínű papírháttéren. Erős peremfény bal felülről, lágy, hosszú árnyék jobb lefelé, finom gőz a bögréből. Négyzetes kivágás, középre rendezett kompozíció, felül hely a címsornak, kellékek és kezek nélkül.",
  "ui.mediaStarter.image3.title": "Sík illusztráció",
  "ui.mediaStarter.image3.tag": "Illusztráció",
  "ui.mediaStarter.image3.prompt": "Sík vektoros illusztráció egy esős ablak melletti hangulatos olvasósarokról. Geometrikus formák, visszafogott ötszínű paletta (krém, terrakotta, mély petrol, égetett szienna, lágy fekete), vékony 1.5px vonalak, színátmenetek és textúrák nélkül, lágy vetett árnyék csak az előtér foteljénél.",
  "ui.mediaStarter.video1.title": "Termék bemutatása",
  "ui.mediaStarter.video1.tag": "Filmszerű",
  "ui.mediaStarter.video1.prompt": "Ötmásodperces termékbemutató: minimalista, prémium bőrápoló üveg tiszta krémszínű kőfelületen, lágy oldalfény a kamera bal oldaláról, lassú kameraközelítés, finom fókuszváltás a kupakról a címkére, visszafogott mozgás, feliratok és emberek nélkül.",
  "ui.mediaStarter.video2.title": "Lámpás közelről",
  "ui.mediaStarter.video2.tag": "Hangulat",
  "ui.mediaStarter.video2.prompt": "Hatmásodperces filmszerű közeli egy fiatal nőről, aki világító papírlámpást tart ködös fenyőerdőben, aranyórában. Kis mélységélesség a szemeken, finom kameraközelítés, lebegő részecskék a meleg fénysugárban, párbeszéd nélkül, csak az erdő hangjaival.",
  "ui.mediaStarter.video3.title": "Drift a neonfényes utcán",
  "ui.mediaStarter.video3.tag": "Akció",
  "ui.mediaStarter.video3.prompt": "Ötmásodperces éjszakai utcai verseny követőfelvétele egy neonfényes, cyberpunk hongkongi sikátorban. Alacsony kamera követ egy matt fekete sportautót, amely szűk kanyarban driftel; elmosódó kerekek, a közeledő neonok lencsecsillanásai, fényt tükröző esőáztatta aszfalt, képernyőfelirat nélkül.",
  "ui.mediaStarter.hyperframes1.title": "Felfedés nagyítóval",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Készíts ötmásodperces kompozíciót egyetlen sor félkövér címszöveggel tiszta vásznon. Egy kerek nagyító haladjon balról jobbra, és finom üvegtöréssel torzítsa az alatta lévő betűket. Használj HyperFrames html-in-canvas megoldást: rögzítsd a szöveg DOM-ját, és helyezz rá lencseshadert egy vfx-liquid-glass stílusú lépésben. A szöveg tiszta CSS, az üveg WebGL-réteg.",
  "ui.mediaStarter.hyperframes2.title": "CRT-termináljelenet",
  "ui.mediaStarter.hyperframes2.tag": "Retró VFX",
  "ui.mediaStarter.hyperframes2.prompt": "Készíts CRT-képernyős kompozíciót: sötét vászon, monospace terminálszöveg beírja a `npx hyperframes init my-video` parancsot, majd elindítja a `claude` programot az 'Add a CRT effect using HTML-in-canvas' utasítással. A html-in-canvas segítségével tegyél finom domború görbületi shadert, pásztázóvonalakat, enyhe kromatikus aberrációt és lágy foszforfényt az élő DOM fölé. A terminálszöveg valódi CSS marad, így a shader előtt tűéles.",
  "ui.mediaStarter.hyperframes3.title": "Glitch-szétesés",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Készíts hatmásodperces kompozíciót főcímmel és egysoros alcímmel sötét vásznon, majd erős digitális glitch-csel: RGB-csatornák szétválása, vízszintes eltolási sávok, rövid képkockaakadás, végül tiszta visszaállás. Rögzítsd az élő DOM-ot html-in-canvas használatával, és tedd rá a glitch-effektet, hogy a betűk valódi CSS-ként maradjanak a shader alatt.",
  "ui.mediaStarter.audio1.title": "Márkanarráció",
  "ui.mediaStarter.audio1.tag": "Beszéd",
  "ui.mediaStarter.audio1.prompt": "Harmincmásodperces, meleg hangú narráció termékbevezető videóhoz: magabiztos, de társalgási, közepes tempóval és rövid szünettel a márkanév után. Szöveg: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' Angolul, semleges észak-amerikai akcentussal.",
  "ui.mediaStarter.audio2.title": "Bevezető narráció",
  "ui.mediaStarter.audio2.tag": "Beszéd",
  "ui.mediaStarter.audio2.prompt": "Húszmásodperces barátságos bevezető narráció egy mobilalkalmazás első indítási képernyőjéhez. Megnyugtató, mosolygós hang, figyelmesen lassú tempó, de ne hasson felolvasottnak. Szöveg: „Üdv a Loopban! Állítsuk be a saját teredet: három gyors kérdés, és kész is vagy. Később mindent megváltoztathatsz.”",
  "ui.mediaStarter.audio3.title": "Történetrészlet felolvasása",
  "ui.mediaStarter.audio3.tag": "Beszéd",
  "ui.mediaStarter.audio3.prompt": "Negyvenöt másodperces filmszerű felolvasás egy nyitórészletből. Mély, kimért hang, lélegzetvétel a mondatok között, kissé bensőséges, mikrofonközeli hangzás. Szöveg: „A város darabokban alszik. Neonreklám villog a ramenpult fölött. A sugárút túloldalán egy ablak világít: az egyetlen, amely még ég az éjfél innenső oldalán.”",
